export function getAuthStatusMessage(pi: ExtensionAPI): string {
  const auth = resolveAuth(pi);
  return auth.source
    ? `[exa] Authenticated via ${auth.source}`
    : "[exa] Not authenticated. Set EXA_API_KEY or use --exa-api-key flag.";
}

// =============================================================================
// Tool Enablement
// =============================================================================

function isAdvancedToolEnabled(pi: ExtensionAPI, config: ExaConfig | null): boolean {
  const advancedFlag = pi.getFlag("--exa-enable-advanced");
  if (typeof advancedFlag === "boolean") {
    return advancedFlag;
  }
  return config?.advancedEnabled ?? false;
}

function isResearchToolEnabled(pi: ExtensionAPI, config: ExaConfig | null): boolean {
  const researchFlag = pi.getFlag("--exa-enable-research");
  if (typeof researchFlag === "boolean") {
    return researchFlag;
  }
  return config?.researchEnabled ?? false;
}

export function isToolEnabledForConfig(pi: ExtensionAPI, config: ExaConfig | null, toolName: string): boolean {
  if (config?.enabledTools && Array.isArray(config.enabledTools)) {
    return config.enabledTools.includes(toolName);
  }

  if (
    toolName === "web_search_exa" ||
    toolName === "web_fetch_exa" ||
    toolName === "web_answer_exa" ||
    toolName === "web_find_similar_exa" ||
    toolName === "exa_research_step" ||
    toolName === "exa_research_status" ||
    toolName === "exa_research_summary" ||
    toolName === "exa_research_reset"
  ) {
    return true;
  }

  if (toolName === "web_search_advanced_exa") {
    return isAdvancedToolEnabled(pi, config);
  }

  if (toolName === "web_research_exa") {
    return isResearchToolEnabled(pi, config);
  }

  return false;
}

/**
 * Exa AI extension for pi.
 *
 * Wires bridgekit's portable Exa tools (./tools.ts) into the pi host via
 * bridgekit 0.9.0's registerPiTools adapter. Per-tool pi metadata
 * (promptSnippet, promptGuidelines) lives on each portable tool's
 * `hostExtras.pi` field and is threaded through to pi's `registerTool`
 * call by the adapter; this module no longer maintains a custom
 * dispatch loop.
 *
 * Error semantics: registerPiTools defaults to `errorHandling: "return"`,
 * so portable `isError: true` results and TypeBox validation failures
 * surface as `{ content, details, isError: true }` rather than thrown
 * `PortableToolExecutionError`. This matches bridgekit's MCP adapter.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { registerPiTools } from "@feniix/bridgekit/pi";
import { getResolvedConfig, isToolEnabledForConfig, resolveAuth } from "./config.js";
import { createExaTools, type ExaToolTimeouts } from "./tools.js";
import { getExaRenderers } from "./tui-renderers.js";

export {
  getAuthStatusMessage,
  isToolEnabledForConfig,
  loadConfig,
  parseConfig,
  resolveAuth,
  resolveConfigPath,
} from "./config.js";
export { formatCrawlResults, formatSearchResults } from "./formatters.js";
export { DEFAULT_MAX_CHARACTERS } from "./web-fetch.js";
export { DEFAULT_NUM_RESULTS } from "./web-search.js";

function registerFlags(pi: ExtensionAPI): void {
  pi.registerFlag("--exa-api-key", {
    description: "Exa AI API key for search operations",
    type: "string",
  });
  pi.registerFlag("--exa-enable-advanced", {
    description: "Enable web_search_advanced_exa tool",
    type: "boolean",
  });
  pi.registerFlag("--exa-enable-research", {
    description: "Enable web_research_exa tool",
    type: "boolean",
  });
  pi.registerFlag("--exa-config-file", {
    description: "Path to custom JSON config file for private overrides such as API keys.",
    type: "string",
  });
  pi.registerFlag("--exa-config", {
    description: "Deprecated alias for --exa-config-file.",
    type: "string",
  });
  pi.registerFlag("--exa-timeout-ms", {
    description: "Default per-call timeout in ms for Exa-backed tools. Overrides the built-in 60000 default.",
    type: "string",
  });
  pi.registerFlag("--exa-research-timeout-ms", {
    description: "Per-call timeout in ms for web_research_exa Agent runs. Overrides the built-in 180000 default.",
    type: "string",
  });
}

function parsePositiveIntFlag(value: string | boolean | undefined): number | undefined {
  if (typeof value !== "string") return undefined;
  const n = Number.parseInt(value.trim(), 10);
  if (!Number.isFinite(n) || n <= 0) return undefined;
  return n;
}

function resolvePiTimeouts(pi: ExtensionAPI): ExaToolTimeouts | undefined {
  const def = parsePositiveIntFlag(pi.getFlag("--exa-timeout-ms"));
  const research = parsePositiveIntFlag(pi.getFlag("--exa-research-timeout-ms"));
  if (def === undefined && research === undefined) return undefined;
  const out: ExaToolTimeouts = {};
  if (def !== undefined) out.default = def;
  if (research !== undefined) out.web_research_exa = research;
  return out;
}

// =============================================================================
// Extension Entry Point
// =============================================================================

export default function exaExtension(pi: ExtensionAPI) {
  registerFlags(pi);

  const resolvedConfig = getResolvedConfig(pi);
  const tools = createExaTools({
    resolveApiKey: () => resolveAuth(pi).apiKey || undefined,
    isToolEnabled: (toolName) => isToolEnabledForConfig(pi, resolvedConfig, toolName),
    timeouts: resolvePiTimeouts(pi),
  }).map((tool) => {
    const renderers = getExaRenderers(tool.name);
    if (!renderers.renderCall && !renderers.renderResult) {
      return tool;
    }
    return {
      ...tool,
      hostExtras: {
        ...tool.hostExtras,
        pi: {
          ...tool.hostExtras?.pi,
          ...renderers,
        },
      },
    };
  });
  registerPiTools(pi, tools);
}

export function createExaTools(opts: ExaToolsOptions = {}): readonly PortableTool<TObject>[] {
  const resolveApiKey = opts.resolveApiKey ?? (() => undefined);
  const isEnabled = opts.isToolEnabled ?? (() => true);
  const planner = opts.planner ?? createResearchPlanner();
  const timeoutFor = (toolName: string) => () => resolveExaToolTimeoutMs(toolName, opts.timeouts);

  const tools: PortableTool<TObject>[] = [];

  if (isEnabled("exa_research_step")) {
    tools.push(
      definePortableTool({
        name: "exa_research_step",
        title: "Exa Research Step",
        description: "Record one step in a stateful, local Exa research planning session without calling Exa APIs.",
        parameters: exaResearchStepParams,
        // Local planner state — each step appends, not idempotent; openWorld=false
        // because no Exa calls are made.
        hostExtras: {
          pi: {
            promptSnippet: "Record iterative research-planning state before retrieval.",
            promptGuidelines: PLANNER_GUIDELINES,
          },
          mcp: { annotations: { readOnlyHint: false, idempotentHint: false, openWorldHint: false } },
        },
        execute(args) {
          try {
            return localToolResult("exa_research_step", planner.recordStep(args));
          } catch (error) {
            return localToolError("exa_research_step", "Exa Research Step", error);
          }
        },
      }),
    );
  }

  if (isEnabled("exa_research_status")) {
    tools.push(
      definePortableTool({
        name: "exa_research_status",
