      }),
    );
  }

  if (isEnabled("exa_research_summary")) {
    tools.push(
      definePortableTool({
        name: "exa_research_summary",
        title: "Exa Research Summary",
        description:
          "Generate a human-readable Exa research plan, Source Pack, or optional suggested web_research_exa payload.",
