+export type ResearchExecutionPlan = Static<typeof executionPlanSchema>;
+
+export function canonicalResearchJson(value: unknown): string {
+  const serialized = JSON.stringify(value, (_key, item: unknown) => {
+    if (typeof item === "number" && !Number.isFinite(item)) throw new Error("Non-finite JSON number.");
