      } finally {
        ancestors.delete(item);
      }
    }
    throw new ResearchArtifactError([
      {
        code: "INVALID_JSON",
        path,
        message: "Use acyclic plain JSON objects, arrays and finite JSON primitives.",
      },
    ]);
  }
  return JSON.stringify(normalize(value, root));
}

