      ? "SCOPE_APPROVAL_REQUIRED"
      : reported > latest.ceilingMicros
        ? "OVERSPEND"
        : blockedOperationIds.length > 0
          ? "UNKNOWN_LIABILITY"
          : proposed === null
            ? "UNCERTAINTY_APPROVAL_REQUIRED"
            : addMoney(exposure, proposed) > latest.ceilingMicros
              ? "INSUFFICIENT_BALANCE"
